package com.hospital.service;
import com.hospital.dao.*;import com.hospital.model.*;import com.hospital.util.*;import java.sql.SQLException;import java.time.*;import java.util.*;
public class AppointmentService {
 private final AppointmentDAO dao=new AppointmentDAO();private final ReportDAO reports=new ReportDAO();private final AuditDAO audit=new AuditDAO();
 public long book(User u,long patient,long doctor,LocalDateTime start,int duration,String reason)throws SQLException{Access.require(u,Role.ADMIN,Role.RECEPTIONIST);if(duration<5||duration>240)throw new IllegalArgumentException("Duration must be between 5 and 240 minutes.");LocalDateTime end=start.plusMinutes(duration);InputValidator.appointmentTime(start,end);long id=dao.book(patient,doctor,start,end,reason,u.id());audit.record(u.id(),"APPOINTMENT_BOOKED","APPOINTMENT",id,"Appointment scheduled");return id;}
 public List<String> list(User u,LocalDate date)throws SQLException{Access.require(u,Role.ADMIN,Role.RECEPTIONIST,Role.DOCTOR);return dao.list(date,u.role()==Role.DOCTOR?u.doctorId():null);}
 public List<String> report(User u,LocalDate from,LocalDate to)throws SQLException{Access.require(u,Role.ADMIN,Role.RECEPTIONIST,Role.DOCTOR);if(to.isBefore(from))throw new IllegalArgumentException("End date must be on or after start date.");return reports.activity(from,to);}
 public void reschedule(User u,long id,long doctor,LocalDateTime start,int duration)throws SQLException{Access.require(u,Role.ADMIN,Role.RECEPTIONIST);if(duration<5||duration>240)throw new IllegalArgumentException("Duration must be between 5 and 240 minutes.");LocalDateTime end=start.plusMinutes(duration);InputValidator.appointmentTime(start,end);dao.reschedule(id,doctor,start,end);audit.record(u.id(),"APPOINTMENT_RESCHEDULED","APPOINTMENT",id,"Appointment rescheduled");}
 public void status(User u,long id,String status)throws SQLException{if(status.equals("CANCELLED"))Access.require(u,Role.ADMIN,Role.RECEPTIONIST);else if(status.equals("COMPLETED")||status.equals("NO_SHOW")){Access.require(u,Role.ADMIN,Role.DOCTOR);if(u.role()==Role.DOCTOR&&u.doctorId()==null)throw new SecurityException("Doctor account is not assigned to a doctor profile.");}else throw new IllegalArgumentException("Unsupported appointment status.");dao.changeStatus(id,status,u.role()==Role.DOCTOR?u.doctorId():null);audit.record(u.id(),"APPOINTMENT_"+status,"APPOINTMENT",id,"Status changed");}
}
